def convertir(textes):
    nombres = []
    for texte in textes:
        texte = texte.strip()
        if texte in ("", "NA"):
            continue
        nombres.append(float(texte.replace(",", ".")))
    return nombres

def filtrer_notes(notes):
    valides = [n for n in notes if 0 <= n <= 20]
    return [valides, len(notes) - len(valides)]

