def moyenne_classe(textes):
    notes = [float(t) for t in textes if t != "NA"]
    absents = len(textes) - len(notes)
    if not notes:
        return [None, absents]
    return [round(sum(notes) / len(notes), 2), absents]

import csv


def moyennes_par_classe(lignes):
    vus = set()
    notes = {}
    for ligne in csv.DictReader(lignes, delimiter=";"):
        cle = (ligne["nom"], ligne["classe"])
        if cle in vus:
            continue
        vus.add(cle)
        texte = ligne["note"].strip()
        if texte in ("", "NA"):
            continue
        note = float(texte.replace(",", "."))
        if 0 <= note <= 20:
            notes.setdefault(ligne["classe"], []).append(note)
    return {classe: round(sum(n) / len(n), 2) for classe, n in notes.items()}
